#!/usr/bin/env python3
"""Entrypoint for news-image-20261122: writes the poster to /output/entry.png.

The poster is drawn by draw_poster.py (PIL) and embedded below as base64:
the grading sandbox runs Python 3.13 standard library only, so no PIL is
available at run time. This program decodes the embedded PNG, validates it
(PNG signature, size, dimensions, every chunk CRC, clean IEND ending) and
writes the exact bytes to /output/entry.png. Two runs write identical bytes.

Outside the grader's container, MAKEFUN_OUTPUT_DIR stands in for /output:
  mkdir -p out && MAKEFUN_OUTPUT_DIR=out python3 main.py
"""

import base64
import binascii
import os
import struct
import sys

# Base64 of poster.png, generated by draw_poster.py (single line).
IMAGE_B64 = ""

MAX_BYTES = 1024 * 1024
MAX_DIMENSION = 1024
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def fail(msg):
    raise SystemExit(f"main.py: {msg}")


def validate_png(data):
    if len(data) > MAX_BYTES:
        fail(f"poster is {len(data)} bytes, over the 1 MiB limit")
    if len(data) < 33 or data[:8] != PNG_SIGNATURE:
        fail("poster does not start with the PNG signature")
    # IHDR is the first chunk: 4-byte length, "IHDR", then width/height.
    width, height = struct.unpack(">II", data[16:24])
    if width > MAX_DIMENSION or height > MAX_DIMENSION:
        fail(f"poster is {width}x{height}, over the 1024x1024 limit")
    # IHDR layout after the dimensions: 1 byte bit depth, 1 byte colour
    # type. The poster is an 8-bit RGB or RGBA image; anything else is not
    # the file this program was built to write.
    bit_depth = data[24]
    colour_type = data[25]
    if bit_depth != 8 or colour_type not in (2, 6):
        fail(f"poster IHDR is bit depth {bit_depth}, colour type "
             f"{colour_type}; expected 8-bit RGB/RGBA")
    # Walk every chunk and check its CRC, so a truncated or corrupted file
    # is rejected instead of written. The walk must end exactly at the end
    # of the file, on the IEND chunk: that is what makes the PNG whole.
    offset = 8
    saw_iend = False
    while offset < len(data):
        if offset + 8 > len(data):
            fail("poster ends mid-chunk")
        (length,) = struct.unpack(">I", data[offset:offset + 4])
        ctype = data[offset + 4:offset + 8]
        data_end = offset + 8 + length
        if data_end + 4 > len(data):
            fail(f"poster chunk {ctype!r} is truncated")
        stored_crc, = struct.unpack(">I", data[data_end:data_end + 4])
        actual_crc = binascii.crc32(data[offset + 4:data_end]) & 0xFFFFFFFF
        if stored_crc != actual_crc:
            fail(f"poster chunk {ctype!r} fails its checksum")
        if ctype == b"IEND":
            saw_iend = True
            offset = data_end + 4
            break
        offset = data_end + 4
    if not saw_iend or offset != len(data):
        fail("poster does not end cleanly on its IEND chunk")
    return width, height


def main():
    if not IMAGE_B64:
        fail("embedded poster is empty (IMAGE_B64 not set)")
    data = base64.b64decode(IMAGE_B64)
    width, height = validate_png(data)
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    target = os.path.join(out_dir, "entry.png")
    with open(target, "wb") as fh:
        fh.write(data)
    print(f"Wrote {target} ({width}x{height}, {len(data)} bytes)")


if __name__ == "__main__":
    main()
